from oauth2_provider.models import Application
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oauthlib.common import generate_token

class RotateApplicationSecretView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, client_id):
        try:
            app = Application.objects.get(client_id=client_id, user=request.user)
        except Application.DoesNotExist:
            return Response({'error': 'Application not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

        new_secret = generate_token(length=64)
        app.client_secret = new_secret
        app.save(update_fields=['client_secret'])
        return Response({
            'client_id': app.client_id,
            'client_secret': new_secret,
            'name': app.name
        })
